-- 1176: туры «Края Вулканов» (volcanoesland.ru) на карточку 1174 (#2245).
--
-- Решение владельца 08.10: «парси туры теперь». Источник — витрина оператора,
-- снятая пробой 712 (08.10.2026): 11 туров с номерами 01–10 и 15 (четыре
-- номера 11–14 на сайте отсутствуют). В тексте — только то, что есть на сайте:
-- описание, программа по дням, состав, что не входит, предупреждения.
--
-- Что НЕ переносится, и почему:
--  - даты: на сайте они либо прошли (02 — лето 2026), либо 2024 года (09);
--    источник дат — оператор, не витрина (разбор владельца 06.10);
--  - «что взять»: сайт отсылает к разделу «Важная информация» без списка;
--    список, написанный за оператора, был бы выдумкой (§4.0);
--  - условия отмены: сайт обещает только возврат за отменённый вертолётный
--    вылет (03, 10) — это не правило отмены брони; поле пусто, пока оператор
--    не назовёт своё;
--  - фото: снимки оператора в репозиторий не переносились (авторские права,
--    согласие не спрашивали); hero возьмёт заглушку по типу места;
--  - у тура 07 на сайте «120 000 ₽ при группе от 6» ниже цены за большую
--    группу (180 000 от 9) — похоже на опечатку; ступень от 6 не переносится,
--    группе 6–8 цену назовёт оператор (исход miss, не выдуманная сумма).
--
-- Опубликованы: is_published = TRUE. Первая редакция заводила черновики до
-- подтверждения цен; 08.10 владелец передал ответ оператора: «цены такие же
-- на 2027 год» — цены подтверждены, туры выходят в каталог и в get_tours.
-- Карточка партнёра остаётся скрытой (is_public = FALSE, 1174): витрину тура
-- этот флаг не закрывает (lib/tours/public-visibility.ts), а страницу
-- организации откроет отдельное слово оператора.
--
-- Цена: price_unit = 'per_person' явно (дефолт колонки — per_tour, а ступени
-- tour_price_tiers работают только при per_person, lib/tours/price-tiers.ts).
-- base_price — цена, вынесенная оператором в заголовок карточки; при группе
-- внутри ступени действует ступень, вне ступеней — «цену называет оператор».
--
-- max_participants: на сайте не указан, а колонка NOT NULL с CHECK
-- max >= min. Поставлен технический потолок набора 15 (яхта — 8 по
-- вместимости, сборная вертолётная экскурсия — 18 по сайту). Уточнить у
-- оператора вместе с ценами. Координаты — главное место маршрута,
-- приблизительно (у маршрута точек много).
--
-- Идемпотентна: вставка только при наличии партнёра и отсутствии slug.

INSERT INTO operator_tours (
  operator_id, title, slug, short_description, description,
  location_type, activity_type, location_name, latitude, longitude,
  base_price, currency, price_unit, min_participants, max_participants,
  duration_hours, duration_type, multi_day_count,
  weather_dependent, difficulty, is_active, is_published,
  program, included, not_included, safety_notes,
  pickup_type, pickup_details, meeting_point,
  price_note, source_url,
  created_at, updated_at
)
SELECT
  p.id, v.title, v.slug, v.short_d, v.descr,
  v.loc_type, v.act_type, v.loc_name, v.lat, v.lng,
  v.price, 'RUB', 'per_person', v.min_p, v.max_p,
  v.dur_h, v.dur_type, v.days,
  TRUE, v.diff, TRUE, TRUE,
  v.program, v.included, v.not_included, v.safety,
  'hotel_pickup', v.pickup, v.pickup,
  v.price_note, v.source_url,
  NOW(), NOW()
FROM partners p
CROSS JOIN (VALUES
  ('Курильское озеро, Долина гейзеров, вулканы Горелый и Авача', 'volcanoesland-kurilskoe-ozero-dolina-geyzerov-gorelyy-avacha', 'Восемь дней по главным местам Камчатки: морская прогулка в бухту Русская, Долина гейзеров и Узон, Курильское озеро, подъём на Горелый, гора Верблюд у Авачинского.',
   'Насыщенное путешествие по главным природным достопримечательностям Камчатки. За одну поездку вы увидите вулканы Горелый, Авачинский и Корякский, совершите морскую прогулку по Авачинской бухте, побываете в Долине гейзеров и посетите Курильское озеро. Курильское озеро — одно из самых известных мест Камчатки и важная часть Кроноцкого заповедника. Сюда едут ради дикой природы, вулканических пейзажей, прозрачной воды, видов на Ильинский вулкан и возможности увидеть один из самых красивых заповедных районов полуострова. Тур подойдёт тем, кто хочет за несколько дней увидеть разные стороны Камчатки: действующие и потухшие вулканы, океанское побережье, горячие источники, национальную культуру. Маршрут сочетает автомобильные переезды, прогулки, морскую экскурсию и вертолётные вылеты по погоде.',
   'volcano', 'sightseeing', 'Паратунка, Долина гейзеров, Курильское озеро', 52.96, 158.25,
   140000::numeric, 1, 15,
   192::numeric, 'multi_day', 8,
   'easy',
   '[{"title": "День 1. Паратунка / Петропавловск-Камчатский", "text": "Встреча в аэропорту Елизово. Трансфер и размещение на базе отдыха в Паратунке или в гостинице Петропавловска-Камчатского. В этот день можно совершить экскурсию на берег Тихого океана. Питание: без питания."}, {"title": "День 2. Морская прогулка в бухту Русская", "text": "Трансфер к причалу. Выход в море на катере вдоль побережья Авачинской бухты мимо скал Три Брата с выходом в открытый океан до бухты Русская, где находится лежбище сивучей. По пути рыбалка на палтуса, терпуга, камбалу, треску и морского окуня, обед из свежепойманной рыбы, дегустация икры морских ежей. Продолжительность 10–12 часов, велика вероятность встречи с косатками и китами. Питание: завтрак, обед."}, {"title": "День 3. Долина гейзеров", "text": "Трансфер (40 мин) на вертодром и вылет в Долину гейзеров. Во время полёта (1 час) — осмотр вулканов Карымский и Малый Семячик с кислотным озером в кратере. Экскурсия (около 1,5 часов) по Долине гейзеров, перелёт в кальдеру Узон и осмотр её геотермальных проявлений (около 40 мин), перелёт в Налычевскую долину, отдых в горячих источниках и обед. Возвращение в гостиницу. Питание: завтрак, обед."}, {"title": "День 4. Курильское озеро", "text": "Трансфер на вертодром и вылет на Курильское озеро (около 1 часа в пути). Наблюдение (около 1,5 часов) за камчатским медведем и лососем, идущим на нерест. Перелёт в кальдеру вулкана Ксудач и её осмотр, затем перелёт на Ходуткинские горячие источники, отдых и обед. Возвращение в гостиницу. Питание: завтрак, обед."}, {"title": "День 5. Вулкан Горелый", "text": "Переезд около 3 часов на машине повышенной проходимости в кальдеру вулкана Горелый. Подъём занимает примерно 2,5 часа, осмотр кратеров — около 1 часа, спуск — 1,5–2 часа. Возвращение в гостиницу. Питание: завтрак, обед."}, {"title": "День 6. Национальная деревня", "text": "Переезд (1 час) в национальную деревню: традиции и быт камчатских аборигенов, концерт национального ансамбля, обед (шурпа из оленины, чай из камчатских трав с лепёшками). В этот день можно совершить экскурсию на мыс Маячный с видами на Тихий океан, Авачинскую бухту и Вилючинский вулкан. Питание: завтрак, обед."}, {"title": "День 7. Вулкан Авачинский, гора Верблюд", "text": "Переезд (1,5 часа) на машине повышенной проходимости на плато между вулканами Авачинский и Корякский. Прогулка (около 3 часов) на гору Верблюд. По желанию участников вместо прогулки — восхождение на Авачинский вулкан: подъём 5–6 часов, осмотр кратера 1 час, спуск 3–4 часа. Размещение в гостинице Петропавловска-Камчатского. Питание: завтрак, обед."}, {"title": "День 8. Трансфер в аэропорт", "text": "Трансфер в аэропорт Елизово."}]'::jsonb,
   ARRAY['проживание в гостиницах', 'питание согласно программе тура', 'морская прогулка в бухту Русская', 'экскурсия в национальную деревню', 'сопровождение группы на вулканы Горелый и Авачинский', 'автомобильные переезды по всему маршруту']::text[],
   ARRAY['вертолётные экскурсии в Долину гейзеров и на Курильское озеро']::text[],
   ARRAY['Вертолётные экскурсии в Долину гейзеров и на Курильское озеро зависят от погоды и выполняются при благоприятных условиях; порядок дней может меняться.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/dolina-geyzerov-kurilskoe-ozero-vulkany-gorelyy-i-avacha/'),
  ('Вулкан Плоский Толбачик', 'volcanoesland-ploskiy-tolbachik', 'Четыре дня в районе трещинных извержений Толбачика: Мёртвый лес, конусы Северного прорыва, лавовые пещеры и подъём к кратеру Плоского Толбачика.',
   'Путешествие в район знаменитых трещинных извержений вулкана Плоский Толбачик. За несколько дней маршрута вы увидите огромный кратер, лавовые потоки, вулканические бомбы, разноцветные шлаковые поля и Мёртвый лес. Плоский Толбачик — один из самых известных вулканов Камчатки. Его пейзажи отличаются от привычных горных маршрутов: застывшая лава, чёрные и красные конусы, следы извержений и открытые виды на вулканическую группу. Маршрут проходит по грунтовым и лесным дорогам, поэтому участники должны быть готовы к длительным переездам на автомобиле повышенной проходимости и прогулкам по лавовым полям.',
   'volcano', 'trekking', 'Вулкан Плоский Толбачик', 55.83, 160.33,
   60000::numeric, 10, 15,
   96::numeric, 'multi_day', 4,
   'easy',
   '[{"title": "День 1. Петропавловск-Камчатский — посёлок Козыревск", "text": "Переезд (8–9 часов) на машине повышенной проходимости КамАЗ в посёлок Козыревск, по пути остановка в кафе в Мильково. Размещение в гостинице посёлка. Питание: ужин."}, {"title": "День 2. Козыревск — Северный прорыв — Мёртвый лес", "text": "Переезд (4–5 часов) к южному склону вулкана Толбачик. Осмотр Мёртвого леса и конусов Северного прорыва, образовавшихся в результате извержения 1975–1976 годов. Установка палаток на базе в Мёртвом лесу (за дополнительную плату — размещение в двухместных домиках). Переезд к конусу «Звезда», экскурсия в лавовые пещеры. Питание: завтрак, обед, ужин."}, {"title": "День 3. Плоский Толбачик", "text": "Переезд около 40 минут к сопке Клешня у подножия вулкана. Подъём к кратеру Плоского Толбачика занимает около 5–6 часов, по пути осмотр лавовых потоков 2012–2013 годов; спуск по пути подъёма 3–4 часа. Альтернатива восхождению — осмотр (4–5 часов) лавовых потоков, конусов и пещер извержения 2012–2013 годов. Возвращение на базу в Мёртвом лесу. Питание: завтрак, обед, ужин."}, {"title": "День 4. Мёртвый лес — Петропавловск-Камчатский", "text": "Переезд (около 12–14 часов) в Петропавловск-Камчатский. Питание: завтрак."}]'::jsonb,
   ARRAY['проживание в гостинице Козыревска и в палатках на базе в Мёртвом лесу', 'автомобильные переезды по всему маршруту на подготовленном для бездорожья КамАЗе', 'питание по программе тура', 'сопровождение группы: гид, помощник гида и повар', 'кемпинговое снаряжение: палатки, спальные мешки, коврики и трекинговые палки']::text[],
   ARRAY['питание в кафе посёлков Сокоч и Мильково', 'проживание в двухместных домиках на базе в Мёртвом лесу (18 000 ₽ за домик)', 'прочие расходы и услуги, не предусмотренные программой']::text[],
   ARRAY['Маршрут проходит по грунтовым и лесным дорогам: длительные переезды на автомобиле повышенной проходимости.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 60 000 ₽ при группе от 10 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/izverzheniya-vulkana-ploskiy-tolbachik/'),
  ('Самые высокие вулканы Камчатки и Долина гейзеров', 'volcanoesland-oblet-klyuchevskoy-gruppy-dolina-geyzerov', 'Облёт Ключевской группы вулканов на вертолёте, база в Мёртвом лесу у Толбачика, вертолётная экскурсия в Долину гейзеров и кальдеру Узон. Восемь дней без десятичасовых переездов по лесной дороге.',
   'В этом туре вы совершите облёт Ключевской группы вулканов, которая насчитывает 4 действующих и 10 потухших вулканов. Вы увидите застывшие лавовые потоки и пещеры, вулканические конусы различных цветов и Мёртвый лес, образовавшиеся в результате трещинных извержений Толбачика 1975–1976 и 2012–2013 годов. От Толбачика вы перелетите на вертолёте в Долину гейзеров — одно из крупнейших гейзерных полей мира — и посетите кальдеру вулкана Узон с кипящими воронками, грязевыми котлами, фумарольными полями и парящими площадками. Особенность тура — труднодоступные места Камчатки посещаются с использованием вертолёта, что избавляет от изнурительного десятичасового автомобильного переезда по лесной дороге.',
   'volcano', 'helicopter', 'Ключевская группа вулканов, Долина гейзеров', 55.83, 160.33,
   520000::numeric, 6, 15,
   192::numeric, 'multi_day', 8,
   'easy',
   '[{"title": "День 1. Паратунка / Петропавловск-Камчатский", "text": "Встреча в аэропорту Елизово. Трансфер и размещение в гостинице Петропавловска-Камчатского или на базе отдыха в Паратунке. Питание: без питания."}, {"title": "День 2. Петропавловск-Камчатский — посёлок Козыревск", "text": "Переезд (8–9 часов) на машине в посёлок Козыревск. Размещение в гостинице посёлка. Питание: завтрак, ужин."}, {"title": "День 3. Облёт Ключевской группы — Мёртвый лес", "text": "Переезд на вертодром Козыревска или Майского. Облёт Ключевской группы вулканов: Ключевская Сопка, Камень, Безымянный, Ушковский, Крестовский, Овальная и Острая Зимина, Плоский и Острый Толбачик, Большая и Малая Удина. Посадка у каньона реки Студёной или горы Поленница. Перелёт к южному склону Толбачика и размещение в домиках на базе в Мёртвом лесу. Питание: завтрак, обед, ужин."}, {"title": "День 4. Северный прорыв — Мёртвый лес", "text": "Осмотр Мёртвого леса и конусов Северного прорыва, образовавшихся в результате извержения 1975–1976 годов. Питание: завтрак, обед, ужин."}, {"title": "День 5. Вулкан Плоский Толбачик", "text": "Переезд (около 40 минут) на машине повышенной проходимости к сопке Клешня у подножия вулкана. Осмотр (4–5 часов) лавовых потоков, конусов и пещер извержения 2012–2013 годов. По желанию участников — восхождение к кратеру Плоского Толбачика: подъём 5–6 часов, спуск 4–5 часов. Питание: завтрак, обед, ужин."}, {"title": "День 6. Долина гейзеров — кальдера Узон — Петропавловск-Камчатский", "text": "Вылет от базы в Мёртвом лесу в Долину гейзеров; во время полёта (около 1 часа) — осмотр Кроноцкого озера, вулканов Кизимен, Крашенинникова и Кроноцкая Сопка. Экскурсия (около 1,5 часов) по Долине гейзеров, перелёт и осмотр (около 1 часа) кальдеры Узон. Перелёт (около 1 часа) в Мильково и переезд (4–5 часов) в Петропавловск-Камчатский. Питание: завтрак."}, {"title": "День 7. Петропавловск-Камчатский", "text": "День отдыха, может быть использован как резервный на случай плохой погоды. По выбору — экскурсия на Курильское озеро, к вулкану Горелый или Авачинский, морская прогулка в бухту Русская (оплачиваются отдельно). Питание: завтрак."}, {"title": "День 8. Трансфер в аэропорт", "text": "Трансфер в аэропорт Елизово."}]'::jsonb,
   ARRAY['проживание в гостиницах и домиках на базе в Мёртвом лесу', 'облёт Ключевской группы вулканов', 'вертолётная экскурсия в Долину гейзеров и кальдеру Узон', 'автомобильные переезды согласно программе', 'питание согласно программе тура', 'сопровождение группы: гид, помощник гида и повар']::text[],
   ARRAY['расходы на проживание и питание, возникшие из-за изменения программы', 'экскурсии на Курильское озеро, к вулканам Горелый и Авачинский, в бухту Русская']::text[],
   ARRAY['Каждый вылет зависит от погоды: возможны задержки, переносы и отмены; перелёт из Козыревска к базе в Мёртвом лесу может быть заменён автомобильным переездом.', 'При отмене вертолётного вылета оператор возвращает деньги за этот полёт.', 'Передвижение в районе трещинных извержений Толбачика (4-й и 5-й дни) — только на автомобиле.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 520 000 ₽ при группе от 6 человек; 410 000 ₽ при группе от 9 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/oblet-klyuchevskoy-gruppy-vulkanov-tolbachik-dolina-geyzerov/'),
  ('Сплав по реке Быстрая, вулканы Горелый и Авачинский', 'volcanoesland-splav-bystraya-gorelyy-avachinskiy', 'Три дня сплава и рыбалки на Быстрой-Малкинской с ночёвками в палатках, затем подъём на Горелый и прогулка к горе Верблюд между Авачинским и Корякским.',
   'Река Быстрая-Малкинская берёт начало в предгорьях Ганальского хребта и течёт почти из центра полуострова на запад, к Охотскому морю. Это вторая по протяжённости река Камчатки. Ширина на участке сплава 50–150 м, скорость течения 1–4 м/с, протяжённость сплава 60 км; он начинается в 130 км от Петропавловска-Камчатского. На всём протяжении возможна рыбалка на гольца, микижу, кижуча и других лососёвых — на спиннинг, в основном на блесну. Во время сплава высока вероятность встречи с медведем. Во второй части тура вы подниметесь на действующий вулкан Горелый (1829 м) с его коллекцией разнообразных кратеров и побываете у подножия Авачинского (2741 м) и Корякского (3456 м) вулканов.',
   'river', 'rafting', 'Река Быстрая-Малкинская, вулкан Горелый', 53.33, 157.51,
   115000::numeric, 9, 15,
   192::numeric, 'multi_day', 8,
   'medium',
   '[{"title": "День 1. Паратунка", "text": "Встреча в аэропорту Елизово. Трансфер и размещение на базе отдыха в Паратунке. Питание: без питания."}, {"title": "День 2. Паратунка — река Быстрая", "text": "Переезд (около 2 часов) к месту начала сплава у посёлка Малки. Сплав и рыбалка. Установка палаточного лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 3. Река Быстрая", "text": "Сплав и рыбалка. Установка второго палаточного лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 4. Река Быстрая — Паратунка", "text": "В первой половине дня сплав до моста, затем переезд (около 4 часов) и размещение на базе отдыха в Паратунке. Отдых в бассейне с термальной водой. Питание: завтрак, обед."}, {"title": "День 5. Вулкан Горелый", "text": "Переезд около 3 часов на машине повышенной проходимости в кальдеру вулкана Горелый. Подъём примерно 2,5 часа, осмотр кратеров около 1 часа, спуск 1,5–2 часа. Возвращение в гостиницу. Питание: завтрак, обед."}, {"title": "День 6. Вулкан Авачинский", "text": "Переезд (1,5 часа) на плато между Авачинским и Корякским вулканами. Прогулка (3–4 часа) на гору Верблюд, переезд в Петропавловск-Камчатский, экскурсия по городу или на берег Тихого океана. Питание: завтрак, обед."}, {"title": "День 7. Петропавловск-Камчатский", "text": "День отдыха. По выбору — экскурсия в Долину гейзеров, на Курильское озеро или морская прогулка в бухту Русская (оплачиваются отдельно). Питание: завтрак."}, {"title": "День 8. Трансфер в аэропорт", "text": "Трансфер в аэропорт Елизово."}]'::jsonb,
   ARRAY['проживание в гостиницах', 'автомобильные переезды по всему маршруту', 'питание согласно программе тура', 'сопровождение группы: гид, помощник гида и повар', 'рафты и общее туристическое снаряжение: палатки, кемпинговое оборудование, посуда']::text[],
   ARRAY['вертолётные экскурсии в Долину гейзеров и на Курильское озеро']::text[],
   ARRAY['Участникам следует быть готовыми к переездам по гравийным и лесным дорогам плохого качества.', 'Во время сплава высока вероятность встречи с медведем.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 140 000 ₽ при группе от 6 человек; 115 000 ₽ при группе от 9 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/splav-po-reke-bystraya-vulkany-gorelyy-i-avachinskiy/'),
  ('Трекинг к вулканам Карымский, Малый Семячик и в Налычево', 'volcanoesland-treking-karymskiy-malyy-semyachik-nalychevo', 'Двенадцать дней с вертолётными забросками: кратер Малого Семячика, переход к Карымскому и Карымскому озеру, источники Академии Наук, затем пешком через Налычево к базе Три Вулкана.',
   'В первой части тура — два выдающихся вулкана. Карымский (1486 м) — наиболее активный вулкан Камчатки, правильный конус в кальдере диаметром около 5 км. Малый Семячик (1560 м) — короткий вулканический хребет из трёх слившихся конусов; в одном из них кратер с озером цвета глубокой бирюзы и отвесными стенами из разноцветных пород. Ещё одна достопримечательность — кратерное озеро Карымское в кальдере вулкана Академии Наук: с севера над ним поднимается дымящийся Карымский, с противоположной стороны — хребет вулкана Академии Наук. Далее маршрут проходит по природному парку Налычево вдоль вулканов Ааг, Арик, Корякский и Авачинский. Парк внесён в список Всемирного наследия ЮНЕСКО и известен ландшафтами и изобилием горячих и холодных минеральных источников.',
   'volcano', 'trekking', 'Вулканы Карымский и Малый Семячик, парк Налычево', 54.05, 159.44,
   260000::numeric, 9, 15,
   288::numeric, 'multi_day', 12,
   'hard',
   '[{"title": "День 1. Паратунка", "text": "Встреча в аэропорту Елизово. Трансфер и размещение на базе отдыха в Паратунке. Можно совершить экскурсию на берег Тихого океана. Питание: без питания."}, {"title": "День 2. Вулкан Малый Семячик", "text": "Вылет на вертолёте к подножию Малого Семячика. Установка палаточного лагеря. Подъём на вулкан несложен и занимает около 2 часов, осмотр кратера с кислотным озером 2–3 часа, спуск по пути подъёма около 1,5 часов. Питание: завтрак, обед, ужин."}, {"title": "День 3. Малый Семячик — вулкан Карымский", "text": "Переход к базе вулканологов у подножия Карымского — трудный, 8–9 часов: по руслам сухих рек через заросли ольхового стланика, после спуска с борта кальдеры — через лавовые поля и отроги вулкана. Лагерь у домика вулканологов, в 700 метрах — ванна горячих источников. Питание: завтрак, обед, ужин."}, {"title": "День 4. Вулкан Двор", "text": "Радиальный выход (9 км в одну сторону) к вулкану Двор у кальдеры Карымского. В хорошую погоду — панорама на вулканы Карымский, Малый Семячик, Жупановский и Карымское озеро. Питание: завтрак, обед, ужин."}, {"title": "День 5. Карымский — Карымское озеро", "text": "Переход к Медвежьим горячим источникам на берегу Карымского озера. Установка лагеря, осмотр окрестностей. Питание: завтрак, обед, ужин."}, {"title": "День 6. Источники Академии Наук", "text": "Радиальный выход (8 км в одну сторону) к источникам Академии Наук на южном берегу Карымского озера: множество струйчатых и фонтанирующих выходов, гейзериты и кремнисто-карбонатные осадки. Питание: завтрак, обед, ужин."}, {"title": "День 7. Карымское озеро — Налычево", "text": "Вылет на вертолёте в Налычевскую долину. Размещение на турбазе Налычево, отдых на Горячереченских источниках. Питание: завтрак, обед, ужин."}, {"title": "День 8. Налычево — река Шумная", "text": "Переход (3–4 часа) к правому притоку реки Шумной через Аагские минеральные источники. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 9. Река Шумная — река Правая Седловинская", "text": "Переход (4–5 часов) через Корякские минеральные источники. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 10. Река Правая Седловинская — база Три Вулкана", "text": "Переход (6–7 часов) через Авачинский перевал к турбазе Три Вулкана у подножия Корякского и Авачинского. Питание: завтрак, обед, ужин."}, {"title": "День 11. База Три Вулкана — Авачинский — Петропавловск-Камчатский", "text": "По желанию участников — восхождение на Авачинский: подъём 5–6 часов, осмотр кратера 1 час, спуск 3–4 часа. Переезд (1,5 часа) и размещение в гостинице Петропавловска-Камчатского. Питание: завтрак."}, {"title": "День 12. Трансфер в аэропорт", "text": "Трансфер в аэропорт Елизово."}]'::jsonb,
   ARRAY['проживание в гостиницах и на базах отдыха', 'вертолётные перелёты к Малому Семячику и от Карымского озера в Налычево', 'автомобильные переезды по всему маршруту', 'питание согласно программе тура', 'сопровождение группы: гид, помощник гида и повар', 'общее туристическое снаряжение: палатки, горелки, посуда']::text[],
   ARRAY[]::text[],
   ARRAY['Заброска вертолётом напрямую зависит от погоды: задержка вылета может составить от нескольких часов до нескольких дней.', 'График прохождения маршрута может быть изменён из-за погоды или других обстоятельств; решение принимает гид на месте.', 'Переход от Малого Семячика к Карымскому — 8–9 часов по руслам сухих рек, стланику и лавовым полям.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 370 000 ₽ при группе от 6 человек; 260 000 ₽ при группе от 9 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/treking-k-vulkanam-karymskiy-malyy-semyachik-i-nalychevo/'),
  ('Трекинг к подножию вулкана Ключевская Сопка', 'volcanoesland-treking-podnozhie-klyuchevskoy', 'Четырнадцать дней от Толбачика через перевалы Толуд и Толбачинский к базам Плотина и Апахончич: подъём к кратеру Толбачика, на борт Безымянного, каньон Сухой Хапицы и Камень Амбон.',
   'Главное достоинство этого трекинга — виды на вулканы Ключевской группы. Вы придёте к самому подножию Ключевской Сопки (4750 м) и Камня (4575 м), подниметесь на борт одного из наиболее активных вулканов Камчатки — Безымянного (2882 м) — и к огромному кратеру Плоского Толбачика (3085 м). Вы увидите каньон реки Сухая Хапица и Камень Амбон — огромную глыбу, отколовшуюся более тысячи лет назад от вулкана Камень при обвале его восточного склона, посетите Мёртвый лес, ярко-красные вулканические конусы и застывшие лавовые потоки извержений Толбачика 1975–1976 и 2012–2013 годов.',
   'volcano', 'trekking', 'Вулкан Ключевская Сопка', 56.06, 160.64,
   180000::numeric, 9, 15,
   336::numeric, 'multi_day', 14,
   'hard',
   '[{"title": "День 1. Паратунка / Петропавловск-Камчатский", "text": "Встреча в аэропорту Елизово. Трансфер и размещение в гостинице Петропавловска-Камчатского или на базе отдыха в Паратунке. Питание: без питания."}, {"title": "День 2. Петропавловск-Камчатский — посёлок Козыревск", "text": "Переезд (8–9 часов) на машине повышенной проходимости в Козыревск. Размещение в гостевом доме посёлка. Питание: завтрак, ужин."}, {"title": "День 3. Козыревск — Северный прорыв — Мёртвый лес", "text": "Переезд (5 часов) к южному склону Толбачика. Осмотр Мёртвого леса и конусов Северного прорыва (извержение 1975–1976 годов). Установка палаток на базе в Мёртвом лесу. Питание: завтрак, обед, ужин."}, {"title": "День 4. Плоский Толбачик", "text": "Переезд около 40 минут к сопке Клешня. Подъём к кратеру Плоского Толбачика около 5–6 часов, по пути лавовые потоки 2012–2013 годов; спуск 3–4 часа. Возвращение на базу. Питание: завтрак, обед, ужин."}, {"title": "День 5. Мёртвый лес — перевал Толуд", "text": "Переезд к сопке Клешня, осмотр лавовых пещер и новых конусов 2012–2013 годов. Переход (5–6 часов, 14 км) к роднику у перевала Толуд. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 6. Перевал Толуд — Толбачинский перевал", "text": "Переход (5–6 часов, около 13 км) через перевал Толуд между Плоским Толбачиком и Большой Удиной (2943 м). Лагерь на Толбачинском перевале или за ним, по наличию воды и погоде. В хорошую погоду — панорама большинства вулканов Ключевской группы. Питание: завтрак, обед, ужин."}, {"title": "День 7. Толбачинский перевал — база Плотина", "text": "Переход (около 8 км) к базе вулканологов Плотина у подножия Безымянного, по пути — гора Поленница из базальтовых столбов. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 8. Вулкан Безымянный", "text": "Подъём на борт Безымянного около 3–4 часов, спуск около 2 часов. При сильной вулканической активности подъём невозможен; решение принимает гид на месте. Питание: завтрак, обед, ужин."}, {"title": "День 9. База Плотина — Сухая Хапица", "text": "Переход (4–5 часов) к реке Сухая Хапица с её каньоном. Установка лагеря, вечером несложный радиальный выход к Камню Амбон. Питание: завтрак, обед, ужин."}, {"title": "День 10. Сухая Хапица — база Апахончич", "text": "Переход (4–5 часов) к базе вулканологов Апахончич с видами на Ключевскую Сопку, Камень и Безымянный. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 11. База Апахончич — Козыревск", "text": "Переезд около 7 часов на машине повышенной проходимости в Козыревск. Размещение в гостевом доме. Питание: завтрак, обед, ужин."}, {"title": "День 12. Козыревск — Петропавловск-Камчатский", "text": "Переезд и размещение в гостинице Петропавловска-Камчатского. Питание: завтрак, обед."}, {"title": "День 13. Петропавловск-Камчатский", "text": "День отдыха. По выбору — экскурсия в Долину гейзеров, на Курильское озеро, к вулкану Горелый или Авачинский, морская прогулка в бухту Русская (оплачиваются отдельно). Питание: завтрак."}, {"title": "День 14. Трансфер в аэропорт", "text": "Трансфер в аэропорт Елизово."}]'::jsonb,
   ARRAY['проживание в гостиницах и гостевых домах', 'автомобильные переезды по всему маршруту', 'питание согласно программе тура', 'сопровождение группы: гид, помощник гида и повар', 'общее туристическое снаряжение: палатки, горелки, посуда']::text[],
   ARRAY['экскурсии в Долину гейзеров, на Курильское озеро, к вулканам Горелый и Авачинский, в бухту Русская']::text[],
   ARRAY['Долгие переезды по гравийным и лесным дорогам плохого качества.', 'Подъём на Безымянный невозможен при сильной вулканической активности; решение принимает гид на месте.', 'График маршрута может быть изменён из-за погоды или других обстоятельств; решение принимает гид на месте.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 230 000 ₽ при группе от 6 человек; 180 000 ₽ при группе от 9 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/treking-k-podnozhiyu-vulkana-klyuchevskaya-sopka/'),
  ('Трекинг вокруг вулкана Плоский Толбачик', 'volcanoesland-treking-vokrug-ploskogo-tolbachika', 'Четырнадцать дней вокруг Толбачика: подъём к кратеру, Северный прорыв, перевалы Толуд и Толбачинский, Марсово поле, база Плотина, каньон Студёной и Поляна эдельвейсов.',
   'Трекинг вокруг Плоского Толбачика — маршрут для тех, кто хочет глубже познакомиться с районом Толбачинских извержений: лавовые поля, конусы, Мёртвый лес, вулканические плато и открытые виды на Ключевскую группу. От короткой поездки на Толбачик этот тур отличается насыщенностью пеших переходов и временем, проведённым среди вулканических ландшафтов: восемь ночей в палатках, переходы через перевалы Толуд и Толбачинский, выход к базе вулканологов Плотина и каньону реки Студёной.',
   'volcano', 'trekking', 'Вулкан Плоский Толбачик', 55.83, 160.33,
   180000::numeric, 9, 15,
   336::numeric, 'multi_day', 14,
   'hard',
   '[{"title": "День 1. Паратунка / Петропавловск-Камчатский", "text": "Встреча в аэропорту Елизово. Трансфер и размещение в гостинице Петропавловска-Камчатского или на базе отдыха в Паратунке. Питание: без питания."}, {"title": "День 2. Петропавловск-Камчатский — посёлок Козыревск", "text": "Переезд (8–9 часов) на машине повышенной проходимости в Козыревск. Размещение в гостевом доме. Питание: завтрак, ужин."}, {"title": "День 3. Козыревск — Мёртвый лес", "text": "Переезд (5 часов) к южному склону Толбачика. Установка палаток на базе в Мёртвом лесу, осмотр окрестностей. Питание: завтрак, обед, ужин."}, {"title": "День 4. Плоский Толбачик", "text": "Переезд около 40 минут к сопке Клешня. Подъём к кратеру Плоского Толбачика около 5–6 часов с осмотром лавовых потоков 2012–2013 годов; спуск 3–4 часа. Возвращение на базу. Питание: завтрак, обед, ужин."}, {"title": "День 5. Северный прорыв", "text": "Осмотр конусов Северного прорыва и Мёртвого леса, образовавшихся в результате извержения 1975–1976 годов. Питание: завтрак, обед, ужин."}, {"title": "День 6. Мёртвый лес — база Толуд", "text": "Переезд к сопке Клешня, осмотр лавовых пещер и новых конусов 2012–2013 годов. Несложный переход (3–4 часа, около 9,5 км) к домику вулканологов у реки Толуд. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 7. База Толуд — река Правый Толбачик", "text": "Переход (7–8 часов, около 14 км) через перевал Толуд между Плоским Толбачиком и Большой Удиной (2943 м). Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 8. Река Правый Толбачик — стоянка Марсово поле", "text": "Переход (3–4 часа, около 7,5 км) через Толбачинский перевал между Плоским Толбачиком и Овальной Зиминой (3081 м). В хорошую погоду — панорама большинства вулканов Ключевской группы. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 9. Марсово поле — база Плотина", "text": "Радиальный выход (5–6 часов) к базе вулканологов Плотина у подножия Безымянного, по пути — гора Поленница из базальтовых столбов. Возвращение в лагерь. Питание: завтрак, обед, ужин."}, {"title": "День 10. Марсово поле — ручей Бараний", "text": "Переход (5–6 часов) по долине реки Студёной с осмотром её каньона. Установка лагеря, вечером несложный выход к Поляне эдельвейсов. Питание: завтрак, обед, ужин."}, {"title": "День 11. Ручей Бараний — Козыревск", "text": "Переход около 3 часов к сопке Копыто, затем переезд 3 часа на машине повышенной проходимости в Козыревск. Размещение в гостевом доме. Питание: завтрак, обед, ужин."}, {"title": "День 12. Козыревск — Петропавловск-Камчатский", "text": "Переезд и размещение в гостинице Петропавловска-Камчатского. Питание: завтрак."}, {"title": "День 13. Петропавловск-Камчатский", "text": "День отдыха. По выбору — экскурсия в Долину гейзеров, на Курильское озеро, к вулкану Горелый или Авачинский, морская прогулка в бухту Русская (оплачиваются отдельно). Питание: завтрак."}, {"title": "День 14. Трансфер в аэропорт", "text": "Трансфер в аэропорт Елизово."}]'::jsonb,
   ARRAY['проживание в гостиницах и гостевых домах', 'автомобильные переезды по всему маршруту', 'питание согласно программе тура', 'сопровождение группы: гид, помощник гида и повар', 'общее туристическое снаряжение: палатки, газовые баллоны, посуда для приготовления пищи']::text[],
   ARRAY['экскурсии в Долину гейзеров, на Курильское озеро, к вулканам Горелый и Авачинский, в бухту Русская']::text[],
   ARRAY['Долгие переезды по гравийным и лесным дорогам плохого качества.', 'График маршрута может быть изменён из-за погоды или других обстоятельств; решение принимает гид на месте.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 180 000 ₽ при группе от 9 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года. На сайте оператора также указано 120 000 ₽ при группе от 6 человек — до подтверждения оператором не переносится.',
   'https://volcanoesland.ru/tours/treking-vokrug-vulkana-ploskiy-tolbachik/'),
  ('Восхождение на вулкан Ключевская Сопка', 'volcanoesland-voskhozhdenie-klyuchevskaya-sopka', 'Экстремальный тур для подготовленных: вертолётная заброска к кратеру Перевальный (2700 м), перевал Вулканологов (3300 м), восхождение по южному склону на Ключевскую Сопку (4750 м), спуск по леднику Богдановича.',
   'Экстремальный и самый сложный тур оператора. Рассчитан на людей с хорошей физической подготовкой и опытом горного туризма. Ключевская Сопка (4750 м) — один из самых активных вулканов Камчатки и мира; при подъёме следует учитывать опасность камнепадов и сильное газовыделение около вершины. Подъём идёт по южному склону от перевала Вулканологов и относится к маршрутам категории сложности 2А. Общее снаряжение и продукты распределяются поровну между всеми участниками, включая сотрудников оператора: общественная нагрузка не более 8 кг на человека. В приготовлении пищи и установке палаток участвуют все; основа питания — сублимированные продукты.',
   'volcano', 'volcano', 'Вулкан Ключевская Сопка', 56.06, 160.64,
   320000::numeric, 6, 15,
   288::numeric, 'multi_day', 12,
   'hard',
   '[{"title": "День 1. Паратунка / Петропавловск-Камчатский", "text": "Встреча в аэропорту Елизово. Трансфер и размещение в гостинице Петропавловска-Камчатского или на базе отдыха в Паратунке. Питание: без питания."}, {"title": "День 2. Петропавловск-Камчатский — посёлок Козыревск", "text": "Переезд (8–9 часов) на машине повышенной проходимости в Козыревск. Размещение в гостевом доме. Питание: завтрак, ужин."}, {"title": "День 3. Козыревск — кратер Перевальный", "text": "Вылет на вертолёте к кратеру Перевальный между Ушковским и Ключевской на высоте 2700 м. Установка палаточного лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 4. Кратер Перевальный — перевал Вулканологов", "text": "Переход (около 6 часов) на перевал Вулканологов между Ключевской Сопкой и Камнем на высоте 3300 м. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 5. Восхождение на Ключевскую Сопку", "text": "Восхождение (8–10 часов) по южному склону, спуск (5–7 часов) в лагерь на перевале. Питание: завтрак, обед, ужин."}, {"title": "День 6. Перевал Вулканологов", "text": "Резервный день на случай плохой погоды. Питание: завтрак, обед, ужин."}, {"title": "День 7. Перевал Вулканологов — кратер Перевальный", "text": "Переход (около 5 часов) к кратеру Перевальный. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 8. Ледник Богдановича, 1900 м", "text": "Переход (около 6 часов) по леднику Богдановича до высоты 1900 м. Установка лагеря. Питание: завтрак, обед, ужин."}, {"title": "День 9. Ледник Богдановича, 1300 м", "text": "Переход (около 6 часов) по леднику до высоты 1300 м. Лагерь у реки Студёной. Питание: завтрак, обед, ужин."}, {"title": "День 10. Ледник Богдановича — сопка Копыто — Козыревск", "text": "Переход (около 6 часов) к сопке Копыто и переезд (около 3 часов) на машине повышенной проходимости в Козыревск. Размещение в гостевом доме. Питание: завтрак, обед, ужин."}, {"title": "День 11. Козыревск — Паратунка", "text": "Переезд и размещение на базе отдыха в Паратунке. Питание: завтрак."}, {"title": "День 12. Трансфер в аэропорт", "text": "Трансфер в аэропорт Елизово."}]'::jsonb,
   ARRAY['проживание в гостиницах и гостевых домах', 'автомобильные переезды по всему маршруту', 'перелёт на вертолёте на высоту 2700 м', 'питание согласно программе тура', 'сопровождение группы: гид и помощник гида', 'общее туристическое снаряжение: палатки, газовые баллоны, посуда для приготовления пищи']::text[],
   ARRAY[]::text[],
   ARRAY['Восхождение на Ключевскую Сопку может представлять опасность для жизни: высокая вулканическая активность, осыпи и камнепады, сильное газовыделение у вершины.', 'Участники обязаны иметь страховой полис с оплатой медико-транспортных расходов вертолётом и поисково-спасательных работ.', 'Требуется хорошая физическая подготовка, выносливость и опыт горного туризма; маршрут категории 2А.', 'График маршрута может быть изменён из-за погоды или других обстоятельств; решение принимает гид на месте.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 320 000 ₽ при группе от 6 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/voskhozhdenie-na-vulkan-klyuchevskaya-sopka/'),
  ('Экспедиционный круиз на Командорские острова', 'volcanoesland-kruiz-komandorskie-ostrova', 'Девять дней на стальной парусной яхте: киты у Шипунского полуострова, остров Медный с котиками и каланами, бухта Командор с могилой Беринга, Северное лежбище, птичьи базары и село Никольское.',
   'Командорские острова — одно из самых удалённых и труднодоступных мест планеты. За исключением села Никольское они совершенно необитаемы, и суровая земля сохранила богатство первозданной природы. Среди океана, отвесных скал и прибоя здесь можно почувствовать себя исследователем и первооткрывателем. Круиз проходит на стальной парусной яхте длиной 20 метров: экипаж 4 человека, пассажиров 8. На яхте две пассажирские каюты на 3 и 5 человек, два туалета, кухня, кают-компания, два поста управления, верхняя палуба с двумя мачтами, лебёдка и две моторные лодки для высадок на необорудованные берега.',
   'sea', 'boat_trip', 'Командорские острова', 55.2, 166.0,
   350000::numeric, 8, 8,
   216::numeric, 'multi_day', 9,
   'easy',
   '[{"title": "День 1. Петропавловск-Камчатский", "text": "Прибытие, встреча, размещение, обсуждение программы рейса, экскурсия и купание в термальных источниках Паратунки."}, {"title": "День 2. Выход в рейс", "text": "В 8 утра выход в рейс на Командорские острова. Наблюдение за морскими млекопитающими в Авачинском заливе и у Шипунского полуострова, фотографирование китов."}, {"title": "День 3. Переход через океан", "text": "Весь день на переходе к острову Медный; по пути наблюдение за китами, подход к ним, фотографирование."}, {"title": "День 4. Остров Медный", "text": "К полудню подход к перешейку Островному; высадка, пешеходный маршрут 4 км к мысу Юго-Восточному с подъёмом на гору Сахарная Голова — самую высокую вершину острова. Встречи с медновскими песцами, северными морскими котиками, сивучами, каланами и антурами. Ночью переход в бухту Гладковскую."}, {"title": "День 5. Бухты Гладковская и Преображенская", "text": "Высадка в бухте Гладковской, осмотр лагуны, фотографирование у водопада; проход к бухте Преображенской, осмотр места бывшего посёлка и старого кладбища алеутов. Ночной переход к острову Беринга в бухту Командор."}, {"title": "День 6. Бухта Командор — бухта Буян", "text": "С рассветом высадка в бухте Командор: могила Витуса Беринга и членов его экипажа, осмотр бухты. Переход вдоль берега к бухте Буян, высадка, продолжение перехода к северной оконечности острова."}, {"title": "День 7. Северное лежбище — Никольское", "text": "Утром высадка на Северное лежбище морских котиков, проход по эстакаде, наблюдение за животными, бывшая база промысловиков. Переход к мысу Северо-Западному и к Никольскому; по пути птичьи базары острова Арий Камень и остров Топорков. В Никольском — музей заповедника и краеведческий музей. В ночь — переход в порт Петропавловска-Камчатского."}, {"title": "День 8. Переход к Шипунскому полуострову", "text": "Переход от острова Беринга к полуострову Шипунскому. Наблюдение за морскими млекопитающими и птицами."}, {"title": "День 9. Петропавловск-Камчатский", "text": "Утром прибытие в порт, окончание рейса."}]'::jsonb,
   ARRAY['проживание в гостинице Петропавловска-Камчатского в первый день', 'проживание на борту парусной яхты в каюте на 3 или 5 человек', 'трёхразовое питание на борту', 'все разрешения и согласования для посещения особо охраняемых территорий и пограничных пунктов', 'экскурсионная программа на борту и во время высадок', 'все трансферы по программе']::text[],
   ARRAY['дополнительные расходы, не предусмотренные программой', 'алкоголь']::text[],
   ARRAY['Круиз ближе к экспедиции: программа зависит от погоды, состояния моря и условий на маршруте.', 'Высадки на необорудованные берега с моторных лодок.']::text[],
   'Встреча в Петропавловске-Камчатском, трансферы по программе включены.',
   'Цена за человека. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/ekspeditsionnyy-kruiz-na-komandorskie-ostrova/'),
  ('Экскурсия в Долину гейзеров и кальдеру вулкана Узон', 'volcanoesland-dolina-geyzerov-kaldera-uzon', 'Однодневная вертолётная экскурсия: облёт Карымского и Малого Семячика, полтора часа в Долине гейзеров, кальдера Узон, обед в Налычевской долине. В составе сборной группы.',
   'Долина гейзеров — каньон с одним из крупнейших гейзерных полей мира, спрятанный в труднодоступном ущелье Кроноцкого биосферного заповедника. Фонтанирующие гейзеры, бурлящие грязевые котлы, бирюзовое озеро, склоны необычной окраски с горячей водой и струями пара вместе с буйной зеленью создают сказочное зрелище. Недалеко — кальдера вулкана Узон, гигантская впадина 9–12 км с кипящими воронками, грязевыми котлами, фумарольными полями и парящими площадками. Особенность места — кратерообразные воронки глубиной до 25–40 м с горячими озёрами необычных расцветок; в восточной части — одна из крупнейших на Камчатке воронок взрыва диаметром 1,65 км с озером Дальним. Экскурсия проходит в составе сборной группы от 18 человек. В разгар летнего сезона пользуется большим спросом и требует предварительного бронирования.',
   'hot_spring', 'helicopter', 'Долина гейзеров, кальдера Узон', 54.43, 160.14,
   97000::numeric, 1, 18,
   5.5::numeric, 'day', NULL,
   'easy',
   '[{"title": "11:00–12:00. Вылет в Долину гейзеров", "text": "Вылет с вертодрома Елизово. Облёт действующих вулканов Карымский и Малый Семячик."}, {"title": "12:00–13:30. Долина гейзеров", "text": "Экскурсия в Долине гейзеров."}, {"title": "13:30–14:30. Кальдера Узон", "text": "Перелёт (10 минут) в кальдеру вулкана Узон и экскурсия по ней."}, {"title": "14:30–16:00. Налычевская долина", "text": "Перелёт до обеденной стоянки в Налычевской долине. Посадка только при хороших погодных условиях."}, {"title": "16:00–16:30. Возвращение", "text": "Возвращение на вертодром Елизово."}]'::jsonb,
   ARRAY['вертолётные перелёты в Кроноцкий заповедник и обратно', 'сборы Кроноцкого заповедника: посещение, сопровождение, информационное обеспечение', 'трансфер гостиница — вертодром — гостиница', 'услуги гида-экскурсовода', 'обед']::text[],
   ARRAY[]::text[],
   ARRAY['Доставка в Кроноцкий заповедник вертолётом напрямую зависит от погоды: задержка вылета может составить от нескольких часов до нескольких дней. Планируйте экскурсию на первые дни пребывания и оставляйте резервные дни.', 'При отмене экскурсии из-за погоды деньги возвращаются в полном объёме.']::text[],
   'Трансфер гостиница — вертодром Елизово — гостиница включён.',
   'Цена за человека в составе сборной группы от 18 человек. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/odnodnevnaya-ekskursiya-v-dolinu-geyzerov-i-kalderu-vulkana-uzon/'),
  ('Автомобильный тур на Курильское озеро', 'volcanoesland-avtotur-kurilskoe-ozero', 'Семь дней без вертолёта: переезд через паромные переправы в Паужетку, 12 км пешком на Курильское озеро мимо Кутхиных батов, два дня наблюдения за медведями на кордоне Озёрный, термальные источники Паужетки.',
   'Курильское озеро — исключительное по красоте место, где можно наблюдать за камчатским медведем и лососем, идущим на нерест: здесь обитает самая большая популяция бурого медведя в мире и каждый год нерестится от 3 до 10 миллионов особей нерки. Озеро расположено на юге полуострова в Южно-Камчатском заказнике, имеет вулканическое происхождение и включено в список Всемирного наследия ЮНЕСКО. В его окрестностях есть всё, чем славится Камчатка: вулканы, лавовые поля, геотермальные проявления, минеральные источники и мощные пемзовые отложения.',
   'lake', 'bears', 'Курильское озеро, Паужетка', 51.45, 157.1,
   150000::numeric, 9, 15,
   168::numeric, 'multi_day', 7,
   'medium',
   '[{"title": "День 1. Паратунка / Петропавловск-Камчатский", "text": "Встреча в аэропорту Елизово. Трансфер и размещение на базе отдыха в Паратунке или в гостинице Петропавловска-Камчатского. Питание: ужин."}, {"title": "День 2. Петропавловск-Камчатский — Паужетка", "text": "Переезд (8–9 часов) в посёлок Паужетка с паромными переправами через реки Большая, Опала и Кошегочек. Размещение в гостевом доме посёлка, отдых в термальных источниках. Питание: завтрак, обед, ужин."}, {"title": "День 3. Паужетка — Курильское озеро", "text": "Переезд (около 30 минут) к реке Озерной. Пешеходный переход (12 км) на Курильское озеро, по пути экскурсия к Кутхиным батам. Палаточный лагерь на кордоне Озёрный. Питание: завтрак, обед, ужин."}, {"title": "День 4. Курильское озеро", "text": "Наблюдение за медведями. Экскурсия на лодках по озеру. Питание: завтрак, обед, ужин."}, {"title": "День 5. Курильское озеро — Паужетка", "text": "Пешеходный переход (12 км) к реке Озерной и переезд в Паужетку. Размещение в гостевом доме, отдых в термальных источниках. Питание: завтрак, обед, ужин."}, {"title": "День 6. Паужетка", "text": "Осмотр окрестностей посёлка. По желанию — радиальный выход к термальным площадкам у геотермальной станции или к Белым водопадам. Питание: завтрак, обед, ужин."}, {"title": "День 7. Паужетка — Паратунка", "text": "Переезд (7–8 часов) и размещение в гостинице в Паратунке. Питание: завтрак, обед."}]'::jsonb,
   ARRAY['проживание в гостиницах и гостевых домах', 'автомобильные переезды по всему маршруту', 'питание согласно программе тура', 'сопровождение группы: гид и повар', 'все сборы Кроноцкого заповедника за услуги на Курильском озере', 'общее туристическое снаряжение: палатки, кемпинговое оборудование, посуда']::text[],
   ARRAY[]::text[],
   ARRAY['Тур проходит по особо охраняемой территории: участники обязаны соблюдать правила поведения на заповедной территории и инструкции сотрудников заповедника и гида.', 'Длительные переезды на автомобиле и возможные задержки на переправах через реки.']::text[],
   'Встреча в аэропорту Елизово, трансфер в гостиницу. Подробности забора уточняет оператор при подтверждении заявки.',
   'Цена за человека: 170 000 ₽ при группе от 6 человек; 150 000 ₽ при группе от 9 человек. Для меньшей группы цену называет оператор. Цены подтверждены оператором на сезон 2027 года.',
   'https://volcanoesland.ru/tours/avtomobilnyy-tur-na-kurilskoe-ozero/')
) AS v(title, slug, short_d, descr, loc_type, act_type, loc_name, lat, lng,
       price, min_p, max_p, dur_h, dur_type, days, diff, program, included,
       not_included, safety, pickup, price_note, source_url)
WHERE p.slug = 'volcanoesland'
  AND NOT EXISTS (
    SELECT 1 FROM operator_tours t
     WHERE t.operator_id::text = p.id::text AND t.slug = v.slug
  );

-- Ступени цены по размеру группы — дословно с витрины (1173, #2246).
INSERT INTO tour_price_tiers (operator_tour_id, min_people, max_people, price_per_person)
SELECT t.id, v.min_people, v.max_people, v.price
FROM (VALUES
  ('volcanoesland-ploskiy-tolbachik', 10, NULL, 60000::numeric),
  ('volcanoesland-oblet-klyuchevskoy-gruppy-dolina-geyzerov', 6, 8, 520000::numeric),
  ('volcanoesland-oblet-klyuchevskoy-gruppy-dolina-geyzerov', 9, NULL, 410000::numeric),
  ('volcanoesland-splav-bystraya-gorelyy-avachinskiy', 6, 8, 140000::numeric),
  ('volcanoesland-splav-bystraya-gorelyy-avachinskiy', 9, NULL, 115000::numeric),
  ('volcanoesland-treking-karymskiy-malyy-semyachik-nalychevo', 6, 8, 370000::numeric),
  ('volcanoesland-treking-karymskiy-malyy-semyachik-nalychevo', 9, NULL, 260000::numeric),
  ('volcanoesland-treking-podnozhie-klyuchevskoy', 6, 8, 230000::numeric),
  ('volcanoesland-treking-podnozhie-klyuchevskoy', 9, NULL, 180000::numeric),
  ('volcanoesland-treking-vokrug-ploskogo-tolbachika', 9, NULL, 180000::numeric),
  ('volcanoesland-voskhozhdenie-klyuchevskaya-sopka', 6, NULL, 320000::numeric),
  ('volcanoesland-avtotur-kurilskoe-ozero', 6, 8, 170000::numeric),
  ('volcanoesland-avtotur-kurilskoe-ozero', 9, NULL, 150000::numeric)
) AS v(slug, min_people, max_people, price)
JOIN partners p ON p.slug = 'volcanoesland'
JOIN operator_tours t ON t.operator_id::text = p.id::text AND t.slug = v.slug
WHERE NOT EXISTS (
  SELECT 1 FROM tour_price_tiers x
   WHERE x.operator_tour_id::text = t.id::text AND x.min_people = v.min_people
);

DO $$
DECLARE n INT;
BEGIN
  SELECT COUNT(*) INTO n FROM operator_tours t
   JOIN partners p ON p.id::text = t.operator_id::text
  WHERE p.slug = 'volcanoesland' AND t.deleted_at IS NULL;
  IF n <> 11 THEN
    RAISE WARNING '1176: у карточки volcanoesland % туров, ожидалось 11', n;
  END IF;
END $$;
